// Test artifacts consumed by the C# suite must match both their sources and their generated bytes.
import { createHash } from 'node:crypto'
import { readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs'

export function writeArtifactStamp(output: URL, artifacts: string[]) {
  const root = new URL('../../../', import.meta.url)
  const inputs = ['web/src/', 'templates/'].flatMap(dir => readdirSync(new URL(dir, root), { recursive: true, encoding: 'utf8' })
    .map(file => dir + file.replaceAll('\\', '/')).filter(file => statSync(new URL(file, root)).isFile()))
    .concat('web/package.json', 'web/package-lock.json')
  const hashes = (files: string[], base: URL) => Object.fromEntries(files.map(file =>
    [file, createHash('sha256').update(readFileSync(new URL(file, base))).digest('hex')]))
  writeFileSync(new URL('stamp.json', output), JSON.stringify({ inputs: hashes(inputs, root), artifacts: hashes(artifacts, output) }))
}
